# English and Malay text for each theme hall.
#
# name: the hall's subject. summary: one or two sentences that restate facts
# from the hall's own 概說 (overview) on kmweb.moa.gov.tw. No fact is added
# that the overview does not state; claims the overview attributes to
# tradition stay attributed. Keyed by the MOA hall id.
#
# T(en_name, en_summary, ms_name, ms_summary)

def T(en, en_s, ms, ms_s):
    return {"en": {"name": en, "summary": en_s}, "ms": {"name": ms, "summary": ms_s}}

